use c6_core::{core_player::{self,initialization::{self as init,capture::*},PlayerInitializations},core_stream::ThroughGlobalAi,map,unit,player_tail};
use sha2::{Digest,Sha256};use serde_json::{Value,json};use std::{collections::{BTreeMap,BTreeSet},path::Path,sync::Arc};
fn digest(b:&[u8])->[u8;32]{Sha256::digest(b).into()}
fn hex(b:&[u8])->String{b.iter().map(|x|format!("{x:02x}")).collect()}
fn main(){let arg=std::env::args().nth(1).unwrap();let m:Value=serde_json::from_slice(&std::fs::read(&arg).unwrap()).unwrap();let base=Path::new(&arg).parent().unwrap();let mut bytes=BTreeMap::new();for k in ["observations_jsonl","runtime_plan_json","static_plan_json","prepared_report_json","exit_json","target_module","target_host","input_save","input_core"]{bytes.insert(k,std::fs::read(base.join(m[k].as_str().unwrap())).unwrap());}
let load=|key:&str|->BTreeMap<String,Vec<u8>>{m[key].as_object().unwrap().iter().map(|(k,v)|(k.clone(),std::fs::read(base.join(v.as_str().unwrap())).unwrap())).collect()};let outputs=load("outputs");let sources=load("source_files");
let named_outputs:Vec<_>=outputs.iter().map(|(name,bytes)|NamedArtifact{name,bytes}).collect();let named_sources:Vec<_>=sources.iter().map(|(name,bytes)|NamedArtifact{name,bytes}).collect();
let capture=admit_capture(CaptureArtifacts{observations_jsonl:&bytes["observations_jsonl"],runtime_plan_json:&bytes["runtime_plan_json"],static_plan_json:&bytes["static_plan_json"],prepared_report_json:&bytes["prepared_report_json"],exit_json:&bytes["exit_json"],target_module:&bytes["target_module"],target_host:&bytes["target_host"],input_save:&bytes["input_save"],input_core:&bytes["input_core"],outputs:&named_outputs,source_files:&named_sources},CaptureLimits::default()).unwrap();assert!(!capture.native_acceptance());assert_eq!(capture.snapshots().len(),129);
let mut bindings=vec![];for s in capture.snapshots(){let role=s.captured_role().unwrap();assert_eq!(role.capture.raw_observation_sha256,digest(&bytes["observations_jsonl"]));assert!(!s.initialization_reconstructed());if !bindings.contains(&role.binding){bindings.push(role.binding.clone());}}
assert_eq!(bindings.len(),3);let shared=map::Limits{max_bytes:256*1024*1024,max_items:64*1024*1024,..map::Limits::default()};let limit=unit::Limits{max_bytes:128*1024*1024,max_items:64*1024*1024};let mut seen=BTreeSet::new();let mut results=vec![];
for binding in bindings{
let raw=match binding.role{init::WireRole::ReadInputCore=>&bytes["input_core"],init::WireRole::SavedOutputCore=>outputs.get(std::str::from_utf8(binding.output_id.as_ref().unwrap()).unwrap()).unwrap()};assert_eq!(digest(raw),binding.core_sha256);let provider=capture.for_binding(&binding);let p=ThroughGlobalAi::decode(raw,shared,limit,binding.clone(),&provider).unwrap();let manager=&p.players;assert!(manager.player_prefix.complete_player_manager_wire());assert_eq!(manager.player_prefix.players().count(),43);assert_eq!(manager.player_prefix.unfinished_player_entries,0);assert!(!manager.player_prefix.initialization_reconstructed());assert_eq!(p.tail,&raw[p.consumed..]);assert!(std::ptr::eq(p.tail.as_ptr(),raw[p.consumed..].as_ptr()));
let(encoded,mi)=manager.player_prefix.encode_prefix_with_items(limit).unwrap();assert_eq!(encoded,raw[manager.core.map_end..manager.consumed]);let(global,gi)=p.global_ai.encode_with_items(limit).unwrap();assert_eq!(global,raw[manager.consumed..p.consumed]);assert_eq!(mi+manager.core.items_used+gi,p.items_used);
let entries:Vec<_>=(0..43).map(|i|manager.player_prefix.encode_player_entry_prefix_with_items(i,limit).unwrap().0).collect();let framing=encoded.len()-entries.iter().map(Vec::len).sum::<usize>();let mut cursor=manager.core.map_end+framing;let mut counts=[0usize;4];let mut ranges=vec![];let mut shapes=vec![];
for (index,(player,entry))in manager.player_prefix.players().zip(&entries).enumerate(){assert_eq!(entry,&raw[cursor..cursor+entry.len()]);let end=cursor+entry.len();assert!(player.header.saved_was_ever_alive());let tail=player.tail.as_ref().unwrap().encode_with_items(player_tail::Context{player_version:47,was_ever_alive:true},limit).unwrap().0;
let parts=[player.ai_military.as_ref().unwrap().encode_with_items(limit).unwrap().0,player.ai_research.as_ref().unwrap().encode_with_items(limit).unwrap().0,player.ai_tactical.as_ref().unwrap().encode_with_items(limit).unwrap().0,player.ai_targets.as_ref().unwrap().encode_with_items(limit).unwrap().0,player.ai_behavior_tree.as_ref().unwrap().encode_with_items(limit).unwrap().0,tail];let start=end-parts.iter().map(Vec::len).sum::<usize>();let military_end=start+parts[0].len();let id=init::PlayerIdentity{manager_index:index as u32,requested_owner:player.requested_owner,record_owner:player.header.owner};let s=provider.for_player_at(id,start).unwrap();assert!(Arc::ptr_eq(&s,&provider.for_player_at(id,start).unwrap()));assert!(provider.for_player_at(id,start+1).is_none());let role=s.captured_role().unwrap();assert_eq!(role.core_range,[start,military_end]);assert_eq!(role.binding,binding);assert_eq!(role.player_id(),player.header.owner);assert_eq!(std::str::from_utf8(&binding.occurrence_id).unwrap().parse::<u64>().unwrap(),role.stream_occurrence);
let mut wrong=binding.clone();wrong.occurrence_id.push(b'x');assert!(capture.for_binding(&wrong).for_player_at(id,start).is_none());let mut wrong=binding.clone();wrong.role=match binding.role{init::WireRole::ReadInputCore=>init::WireRole::SavedOutputCore,init::WireRole::SavedOutputCore=>init::WireRole::ReadInputCore};assert!(capture.for_binding(&wrong).for_player_at(id,start).is_none());
let shape=match &role.states{RoleStates::Read{read_initialized,..}=>read_initialized.vectors.allowed.size_u32!=0,RoleStates::Write{guard,..}=>guard.vectors.allowed.size_u32!=0};assert_eq!(player.ai_military.as_ref().unwrap().operation_types.is_some(),shape);shapes.push(shape);ranges.push(json!({"index":index,"requested":player.requested_owner,"owner":player.header.owner,"entry":[cursor,end],"military":[start,military_end],"frame":role.frame_id,"owner_lifetime":role.owner_lifetime_id}));counts[0]+=player.units.records.entries.len();counts[1]+=player.cities.records.entries.len();counts[2]+=player.districts.records.entries.len();counts[3]+=player.formations.entries.len();cursor=end;}
assert_eq!(cursor,manager.consumed);assert_eq!(counts,[1262,245,1284,1250]);assert!(core_player::Prefix::decode_player_manager_conditional_at(manager.core.tail,limit,binding.clone(),&provider,manager.core.map_end+1).is_err());
let key=(binding.core_sha256,shapes.clone());let caps=seen.insert(key);if caps{let exact=map::Limits{max_bytes:p.consumed,max_items:p.items_used,max_allocation:manager.core.logical_allocation_used,..shared};let post=unit::Limits{max_bytes:p.consumed-manager.core.map_end,max_items:p.items_used-manager.core.items_used};assert!(ThroughGlobalAi::decode(raw,exact,post,binding.clone(),&provider).is_ok());for short in [map::Limits{max_bytes:exact.max_bytes-1,..exact},map::Limits{max_items:exact.max_items-1,..exact},map::Limits{max_allocation:exact.max_allocation-1,..exact}]{assert!(ThroughGlobalAi::decode(raw,short,post,binding.clone(),&provider).is_err());}for short in [unit::Limits{max_bytes:post.max_bytes-1,..post},unit::Limits{max_items:post.max_items-1,..post}]{assert!(ThroughGlobalAi::decode(raw,exact,short,binding.clone(),&provider).is_err());}
let manager_exact=unit::Limits{max_bytes:encoded.len(),max_items:mi};assert_eq!(manager.player_prefix.encode_prefix_with_items(manager_exact).unwrap(),(encoded.clone(),mi));for short in [unit::Limits{max_bytes:manager_exact.max_bytes-1,..manager_exact},unit::Limits{max_items:manager_exact.max_items-1,..manager_exact}]{assert!(manager.player_prefix.encode_prefix_with_items(short).is_err());}}
results.push(json!({"role":format!("{:?}",binding.role),"core_sha256":hex(&binding.core_sha256),"stream_occurrence":std::str::from_utf8(&binding.occurrence_id).unwrap(),"output_id":binding.output_id.as_ref().map(|b|std::str::from_utf8(b).unwrap()),"map_end":manager.core.map_end,"manager_end":manager.consumed,"global_end":p.consumed,"total_items":p.items_used,"post_map_items":p.items_used-manager.core.items_used,"tail_bytes":p.tail.len(),"counts":counts,"whole_prefix_caps_tested":caps,"framing_shapes":shapes,"ranges":ranges}));
}
println!("{}",json!({"schema":"independent-contextual-native3-review-v1","candidate_sha256":hex(&digest(&std::fs::read(std::env::current_exe().unwrap()).unwrap())),"roles":results,"source_only_synthetic_contexts":false,"original_execution":false,"native_read_effects":false,"world_import":false}));}
